      const inbox = await inboxResponse.json();
      const inboxUlid = inbox.item._ulid;

      // First triage — defer
      const firstResponse = await request.post(`${DAEMON_URL}/api/triage`, {
        data: {
          inbox_ref: `@${inboxUlid}`,
          action: 'defer',
          reasoning: 'First decision',
        },
