   284→        const overrideBy = body.override_by || getAuthor(ctx.config?.identity?.author);
   285→
   286→        // AC: @triage-daemon-api ac-4 - Set override fields and update action
   287→        record.override_reasoning = body.reasoning;
   288→        record.override_by = overrideBy;
   289→        record.override_at = new Date().toISOString();
   290→        record.action = body.action as TriageAction;
   291→        record.updated_at = new Date().toISOString();
   292→
   293→        // Re-triage if already acted on (allows re-acting with new action)
   294→        // Clear stale execution metadata to avoid leaking previous action results
   295→        if (record.status === 'acted_on') {
   296→          record.status = 'triaged';
   297→          record.acted_at = undefined;
   298→          record.result_ref = undefined;
   299→        }
   300→
   301→        await saveTriageRecord(ctx, record);
   302→
   303→        // AC: @trait-api-endpoint ac-5 - Shadow commit
   304→        await commitIfShadow(ctx.shadow, `triage: override ${record._ulid.slice(0, 8)}`);
   305→
   306→        // AC: @triage-daemon-api ac-4 - Broadcast triage:updates
   307→        pubsub.broadcast('triage:updates', 'triage_record_updated', {
   308→          ulid: record._ulid,
   309→          action: 'override',
   310→          new_action: record.action,
   311→        }, projectContext.path);
   312→
   313→        return {
   314→          success: true,
   315→          record,
   316→        };
   317→      },
   318→      {
   319→        params: t.Object({
   320→          ref: t.String(),
   321→        }),
   322→        body: t.Object({
   323→          action: t.String(),
   324→          reasoning: t.String(),
   325→          override_by: t.Optional(t.String()),
   326→        }),
   327→      }
   328→    )
   329→
   330→    // AC: @triage-daemon-api ac-5, ac-8, ac-9 - Execute a triage action
   331→    // AC: @trait-api-endpoint ac-1, ac-5 - JSON response, shadow commit
   332→    .post(
   333→      '/:ref/act',
   334→      async ({ params, error: errorResponse, projectContext }) => {
   335→        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
   336→        const ctx = await initContext(projectContext.path);
   337→        const records = await loadTriageRecords(ctx);
   338→
   339→        // AC: @trait-api-endpoint ac-2 - Resolve ref
   340→        const record = findTriageRecordByRef(records, params.ref);
   341→        if (!record) {
   342→          return errorResponse(404, {
   343→            error: 'not_found',
   344→            message: `Triage record reference "${params.ref}" not found`,
   345→            suggestion: 'Use kspec triage list or GET /api/triage to find valid triage record references',
   346→          });
   347→        }
   348→
   349→        // AC: @triage-daemon-api ac-8 - Already acted on → 409
   350→        if (record.status === 'acted_on') {
   351→          return errorResponse(409, {
   352→            error: 'invalid_transition',
   353→            message: 'Triage record has already been acted on',
   354→            current: record.status,
   355→            suggestion: 'Use override to change the decision before acting again',
   356→          });
   357→        }
   358→
   359→        // AC: @triage-daemon-api ac-9 - Pending (no decision) → 422
   360→        if (record.status === 'pending') {
   361→          return errorResponse(422, {
   362→            error: 'incomplete_record',
   363→            message: 'No decision has been recorded for this triage record. Complete triage first.',
   364→            suggestion: 'Use POST /api/triage to record a decision, or kspec triage record <inbox-ref> --action <action> --reasoning <text>',
   365→          });
   366→        }
   367→
   368→        // AC: @triage-daemon-api ac-5 - Execute the action
   369→        const result = await executeTriageAction(record, ctx);
   370→
   371→        // Transition to acted_on
   372→        record.status = 'acted_on';
   373→        record.acted_at = new Date().toISOString();
   374→        if (result.resultRef) {
   375→          record.result_ref = result.resultRef;
   376→        }
   377→        record.updated_at = new Date().toISOString();
   378→
   379→        await saveTriageRecord(ctx, record);
   380→
   381→        // AC: @trait-api-endpoint ac-5 - Shadow commit
   382→        await commitIfShadow(ctx.shadow, `triage: act ${record._ulid.slice(0, 8)}`);
   383→
   384→        // AC: @triage-daemon-api ac-5 - Broadcast triage:updates
   385→        pubsub.broadcast('triage:updates', 'triage_record_acted', {
   386→          ulid: record._ulid,
   387→          action: record.action,
   388→          result_ref: record.result_ref,
   389→        }, projectContext.path);
   390→
   391→        return {
   392→          success: true,
   393→          record,
   394→        };
   395→      },
   396→      {
   397→        params: t.Object({
   398→          ref: t.String(),
   399→        }),
   400→      }
   401→    );
   402→}
